'use strict';

// 瞬时网络错误码白名单；名单之外的错误一律不重试（fail-closed）。
const TRANSIENT_NETWORK_CODES = new Set([
  'ECONNRESET',
  'ETIMEDOUT',
  'ECONNREFUSED',
  'EAI_AGAIN',
  'EPIPE',
  'EHOSTUNREACH',
  'ENETUNREACH',
]);

const MAX_ATTEMPTS = 3;

function isTransientNetworkFailure(error) {
  if (error === null || typeof error !== 'object') return false;
  if (error.transient === true) return true;
  return typeof error.code === 'string' && TRANSIENT_NETWORK_CODES.has(error.code);
}

function sendWithRetry(rows, client, attempt) {
  return client.send(rows).catch((error) => {
    if (attempt >= MAX_ATTEMPTS || !isTransientNetworkFailure(error)) throw error;
    return sendWithRetry(rows, client, attempt + 1);
  });
}

function importOrders(rows, client) {
  return sendWithRetry(rows, client, 1);
}

